foreach ($a in $archivos) {
    $destino = Join-Path $raiz $a.ruta
    $carpeta = Split-Path -Parent $destino
    if (-not (Test-Path $carpeta)) { New-Item -ItemType Directory -Path $carpeta -Force | Out-Null }
    [IO.File]::WriteAllBytes($destino, [Convert]::FromBase64String(($a.b64 -replace '\s','')))
    Write-Host ("  OK  " + $a.ruta) -ForegroundColor Green
}

function Buscar($nombre) {
    $p = Get-Command $nombre -ErrorAction SilentlyContinue
    if ($p) { return $p.Source }
    foreach ($r in @("C:\Program Files\PostgreSQL","C:\Program Files (x86)\PostgreSQL")) {
        if (-not (Test-Path $r)) { continue }
        foreach ($v in (Get-ChildItem $r -Directory -EA SilentlyContinue |
            Sort-Object { if ($_.Name -match '^(\d+)') { [int]$Matches[1] } else { 0 } } -Descending)) {
            $ruta = Join-Path $v.FullName "bin\$nombre.exe"
            if (Test-Path $ruta) { return $ruta }
        }
    }
    return $null
}
$pyExe = $null; $pyArgs = @()
foreach ($c in @(@{ exe = "py"; args = @("-3") }, @{ exe = "python"; args = @() })) {
    if (-not (Get-Command $c.exe -ErrorAction SilentlyContinue)) { continue }
    $v = & $c.exe @($c.args) --version 2>&1 | Out-String
    if ($v -match "Python (\d+)\.(\d+)" -and [int]$Matches[1] -eq 3 -and [int]$Matches[2] -ge 11) {
        $pyExe = $c.exe; $pyArgs = $c.args; break
    }
}
if (-not $pyExe) { Write-Host "No encuentro Python 3.11+." -ForegroundColor Red; Read-Host "Enter"; exit 1 }
$PSQL = Buscar "psql"
if (-not $PSQL) { Write-Host "No encuentro psql." -ForegroundColor Red; Read-Host "Enter"; exit 1 }
$env:PGPASSWORD = "vigia"
$env:PGOPTIONS = "-c client_min_messages=warning"

Write-Host ""
Write-Host "Consultando tu base (solo lectura)..." -ForegroundColor Cyan
$antes = $ErrorActionPreference
$ErrorActionPreference = "Continue"
& $PSQL -h localhost -U vigia -d vigia -tA -f "panel.sql" -o "panel.json" 2>&1 | Out-Host
$codigo = $LASTEXITCODE
$ErrorActionPreference = $antes
if ($codigo -ne 0) { Write-Host "FALLO la consulta." -ForegroundColor Red; Read-Host "Enter"; exit 1 }

Write-Host "Dibujando el panel..." -ForegroundColor Cyan
$ErrorActionPreference = "Continue"
& $pyExe @pyArgs -m vigia.panel 2>&1 | Out-Host
$codigo = $LASTEXITCODE
$ErrorActionPreference = $antes
if ($codigo -ne 0) { Write-Host "FALLO al dibujar." -ForegroundColor Red; Read-Host "Enter"; exit 1 }

Write-Host ""
Write-Host "Abriendo panel.html en tu navegador..." -ForegroundColor Green
Start-Process (Join-Path $raiz "panel.html")
try { Stop-Transcript | Out-Null } catch { }
Start-Sleep -Seconds 2
